<span class="line">    <span class="token keyword">KEY</span> <span class="token identifier"><span class="token punctuation">\`</span>idx_type_date<span class="token punctuation">\`</span></span> <span class="token punctuation">(</span><span class="token identifier"><span class="token punctuation">\`</span>leaderboard_type<span class="token punctuation">\`</span></span><span class="token punctuation">,</span> <span class="token identifier"><span class="token punctuation">\`</span>snapshot_date<span class="token punctuation">\`</span></span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
