<span class="line">    <span class="token identifier"><span class="token punctuation">\`</span>rank<span class="token punctuation">\`</span></span> <span class="token keyword">INT</span> <span class="token keyword">UNSIGNED</span> <span class="token operator">NOT</span> <span class="token boolean">NULL</span> <span class="token keyword">COMMENT</span> <span class="token string">&#39;排名&#39;</span><span class="token punctuation">,</span></span>
